ST.xhtml:p:
R_Trigger(CLK := g_bAvoidOpen);

IF R_Trigger.Q THEN
  g_bAvoidOpen := FALSE;
  g_bAvoidDone := FALSE;
  nAvoidState := 80;
END_IF;

IF g_bBlankCylinderEnable THEN
  IF (g_nBlankClylinderCount >= 1 AND g_bBlankingStateUp1) OR 
     (g_nBlankClylinderCount >= 2 AND g_bBlankingStateUp2) OR
     (g_nBlankClylinderCount >= 3 AND g_bBlankingStateUp3) OR
     (g_nBlankClylinderCount >= 4 AND g_bBlankingStateUp4) OR
     (g_nBlankClylinderCount >= 5 AND g_bBlankingStateUp5) THEN
    g_bFrontSustainStatus := FALSE;
  ELSE
    g_bFrontSustainStatus := TRUE;(*true为下料都下降完成*)
  END_IF;
ELSIF g_bFrontSustainEnable THEN
  IF (g_nFrontSusutainCount >= 1 AND Axis_Sustain4.NCTOPLC.SETPOS >= 0.1) OR
     (g_nFrontSusutainCount >= 2 AND Axis_Sustain5.NCTOPLC.SETPOS >= 0.1) OR
     (g_nFrontSusutainCount >= 3 AND Axis_Sustain6.NCTOPLC.SETPOS >= 0.1) THEN
    g_bFrontSustainStatus := FALSE;
  ELSE
    g_bFrontSustainStatus := TRUE;
  END_IF;
ELSE
  g_bFrontSustainStatus := TRUE;
END_IF;

IF g_bTurnCylinderEnable THEN(*g_bTurnState1 =1是上升到位*)
  IF (g_nTurnCylNum >= 1 AND g_bTurnState1) OR (g_nTurnCylNum >= 2 AND g_bTurnState2) OR
     (g_nTurnCylNum >= 3 AND g_bTurnState3) OR (g_nTurnCylNum >= 4 AND g_bTurnState4) OR
     (g_nTurnCylNum >= 5 AND g_bTurnState5) THEN
    g_bTurnStatus := FALSE;
  ELSE
    g_bTurnStatus := TRUE;(*true为翻转都下降完成*)
  END_IF;
ELSE
  g_bTurnStatus := TRUE;
END_IF;

IF Axis_Z.NCTOPLC.HOMINGSTATE AND g_bZAxisZero AND Axis_Z.NCTOPLC.ACTPOS >= g_fLiftCoord - 0.1 THEN
  g_bZAvoidStatus := TRUE;(*true为 回过零并Z轴安全高度及以上*)
ELSE
  g_bZAvoidStatus := FALSE;
END_IF;

CASE nAvoidState OF
  0:
    nAvoidState := 0;
  1:
    IF g_bFrontSustainStatus AND g_bTurnStatus AND g_bZAvoidStatus THEN
      nAvoidState := 0;
      g_bAvoidDone := TRUE;
    ELSE
      nAvoidState := 80;
    END_IF;
  80: (*如果z回过零,直接调用绝对运动到安全高度,如果没回过零，并且没有压着零位，提示，压着零位，可移动*)
    IF Axis_Z.NCTOPLC.HOMINGSTATE THEN
      nAvoidState := 81;
    ELSE
      IF g_bZAxisZero THEN(*压着零位*)
        nAvoidState := 83;
      ELSE
        g_b3ClawZPosError := TRUE;
        nAvoidState := 0;
      END_IF; 
    END_IF; 
  81:(*deng Z zhuangtai wei kongxian*) 
    IF Axis_Z.NCTOPLC.AxisState = 2 THEN
      nAvoidState := 82;
    END_IF;
  82:(*z绝对运动到安全高度*) 
    g_fZAbsPosition := g_fLiftCoord;
    g_bZAbsExecute := TRUE;
    nAvoidState := 83;
  83:(*翻转放平*)
    g_bTurnUpDownOpen := TRUE;
    g_nTurnType := 0;
    nAvoidState := 84;
  84:(*等待翻转放平完成*)  
    IF g_bTurnUpDownDone THEN
      nAvoidState := 90;
    END_IF;
  90:(*发送下料命令*)
    g_bFrontSustainUpDown := TRUE;
    g_nFrontSustainMoveType := 0;
    nAvoidState := 110;
  110:
    IF ((Axis_Z.NCTOPLC.HOMINGSTATE AND g_bZAbsDone) OR (NOT Axis_Z.NCTOPLC.HOMINGSTATE AND g_bZAxisZero)) AND g_bTurnUpDownDone AND g_bFrontSustainUpDownDone THEN
      g_bZAbsExecute := FALSE;
      nAvoidState := 140;
    ELSIF g_bPlcPauseBuffer THEN
      g_bZAbsExecute := FALSE;
      nAvoidState := 120;
    END_IF;
  120:(*暂停后开始，Z轴上抬完成，直接等待翻转和下料下降完成，Z轴未上抬完成，重新开始*)
    IF g_bPlcStartBuffer THEN
      IF Axis_Z.NCTOPLC.ACTPOS > g_fLiftCoord - 0.1 THEN
        nAvoidState := 130;
      ELSE
        nAvoidState := 80;
      END_IF;
    END_IF;
  130:
    IF g_bTurnUpDownDone AND g_bFrontSustainUpDownDone THEN
      nAvoidState := 140;
    END_IF;
  140:
    IF g_bFrontSustainStatus AND g_bTurnStatus AND ((Axis_Z.NCTOPLC.HOMINGSTATE AND g_bZAvoidStatus) OR (NOT Axis_Z.NCTOPLC.HOMINGSTATE AND g_bZAxisZero)) THEN
      g_bAvoidDone := TRUE;
    ELSE
      IF NOT g_bFrontSustainStatus THEN
        g_b3ClawFrontPosError := TRUE;
      END_IF;
      IF NOT g_bTurnStatus THEN
        g_b3ClawTurnPosError := TRUE;
      END_IF;
      IF NOT g_bZAvoidStatus THEN
        g_b3ClawZPosError := TRUE;
      END_IF;
    END_IF;
    nAvoidState := 0;
END_CASE;

IF g_bPlcResetBuffer THEN
  nAvoidState := 0;
  g_bZAbsExecute := FALSE;
  g_bTurnUpDownOpen := FALSE;
  g_bFrontSustainUpDown := FALSE;
END_IF;
g_noClaw3AvoidState := nAvoidState;
